fn solve(word: Vec<char>) -> Vec<char> {
    // Define the letters in Set A
    let a_letters = [
        'A', 'E', 'F', 'H', 'I', 'K', 'L', 'M', 'N',
        'T', 'V', 'W', 'X', 'Y', 'Z',
    ];

    // Build a lookup table for Set A
    let mut is_in_a = [false; 26];
    for &c in &a_letters {
        is_in_a[(c as u8 - b'A') as usize] = true;
    }

    // Check if every character is in Set A
    let all_in_a = word.iter().all(|&c| {
        let idx = (c as u8 - b'A') as usize;
        is_in_a[idx]
    });

    // Check if every character is in Set B (i.e., not in Set A)
    let all_in_b = word.iter().all(|&c| {
        let idx = (c as u8 - b'A') as usize;
        !is_in_a[idx]
    });

    // If all letters are in A or all are in B, return "YES", otherwise "NO"
    if all_in_a || all_in_b {
        vec!['Y', 'E', 'S']
    } else {
        vec!['N', 'O']
    }
}